<?php defined('_JEXEC') or die; use Joomla\CMS\Router\Route;use Joomla\Component\Academy\Site\Helper\RouteHelper;use Joomla\Component\Academy\Site\Helper\ListExcerptHelper;use Joomla\CMS\HTML\HTMLHelper;?>
<div class="com-academy-category"><h1><?php echo htmlspecialchars($this->category->title,ENT_QUOTES,'UTF-8');?></h1><?php if($this->category->description):?><div><?php echo $this->category->description;?></div><?php endif;?><?php foreach($this->items as $item):$url=Route::_(RouteHelper::getPostRoute($item->id.':'.$item->alias,$item->catid,$item->language??'*'));?><article class="mb-4"><h2><a href="<?php echo $url;?>"><?php echo htmlspecialchars($item->title,ENT_QUOTES,'UTF-8');?></a></h2><?php $item->summary=HTMLHelper::_('content.prepare',$item->summary,'','com_academy.category');echo ListExcerptHelper::render($item,$item->params);?><a href="<?php echo $url;?>">Read more</a></article><?php endforeach;?><?php if(!$this->items):?><p>No posts in this category.</p><?php endif;?><?php echo $this->pagination->getPagesLinks();?></div>
